mkdir -p /tmp/claude-0/-home-user-Claudinite/d9004ddb-cf5d-503c-bf7e-b4a5342fe943/scratchpad && cat > /tmp/claude-0/-home-user-Claudinite/d9004ddb-cf5d-503c-bf7e-b4a5342fe943/scratchpad/scan.mjs <<'EOF'
import { execSync } from 'node:child_process';
import fs from 'node:fs';

const sh = (c) => execSync(c, { encoding: 'utf8', maxBuffer: 1 << 28 });
const tracked = sh('git ls-files').trim().split('\n');

const packs = new Set();
for (const f of tracked) {
  const m = /^packs\/([^/]+)\//.exec(f) || /^\.claudinite\/local\/packs\/([^/]+)\//.exec(f);
  if (m) packs.add(m[1]);
}
const tasks = new Set();
const skills = new Set();
for (const f of tracked) {
  let m = /(?:^|\/)tasks\/([^/]+)\/task\.json$/.exec(f);
  if (m) tasks.add(m[1]);
  m = /(?:^|\/)skills\/([^/]+)\/SKILL\.md$/.exec(f);
  if (m) skills.add(m[1]);
}
const checks = new Set();
for (const f of tracked.filter((f) => f.endsWith('declared-checks.json'))) {
  try {
    const j = JSON.parse(fs.readFileSync(f, 'utf8'));
    for (const c of (Array.isArray(j) ? j : j.checks || [])) if (c.id) checks.add(c.id);
  } catch {}
}
for (const f of tracked) {
  const m = /(?:^|\/)worldRules\/([^/]+)\.mjs$/.exec(f);
  if (m) checks.add(m[1]);
}

const kinds = { pack: packs, task: tasks, skill: skills, check: checks };
const out = {};
for (const [kind, set] of Object.entries(kinds)) out[kind] = [...set].sort();
