  "failureMessage": "git's auto-gc detaches and keeps writing under .git after the command returns, so the fixture's removal races it: the suite passes locally and CI fails with ENOTEMPTY",
  "scanFiles": "/\\.test\\.mjs$/",
  "scanTracked": true,
  "scanIgnoringComments": true,
  "checkEachFile": [
    {
      "whenFileMatches": [
        "/(?:execFileSync|execSync|spawnSync|execFile|spawn)\\(\\s*'git'/",
        "/'(?:init|clone)'/"
      ],
      "require": "/gc\\.autoDetach/",
      "what": "builds a throwaway git repo with a spawn of its own, so git's housekeeping outlives the command that started it",
      "fix": "call the shared runner - `import { git } from '<relative>/engine-tests/helpers.mjs'`, then `git(root, 'init', '-q')` - or spawn with its GIT_CONFIG env, which holds gc.autoDetach and maintenance.auto off"
    }
  ]
}
{
  "id": "no-new-long-dashes",
  "severity": "blocking",
  "scope": "work",
  "since": "2026-09-20",
  "failureMessage": "the owner writes with hyphens; a long dash is a model's habit, and a JSON round trip turns the ones already there into escapes nobody meant to write",
  "excludeFileClasses": [
    "testFiles"
  ],
  "forbidAddedLinesMatching": [
    {
      "inFilesMatching": "/^(?!\\.claudinite\\/shared\\/).*$/",
      "match": "/[–—]|\\\\u201[34]/",
      "unlessLineMatches": "/^\\s*\"match\": /",
      "what": "adds a long dash: \"{match}\"",
      "fix": "use a hyphen, a comma or a full stop; a line the change merely moved keeps its text, so re-add it as it was"
    }
  ]
}
{
  "id": "migration-record-paths-resolve",
  "severity": "blocking",
  "since": "2026-09-20",
  "failureMessage": "a canon path in a migration record fails open — an unreadable probe reads as \"not capable\", a missing template is skipped — so a move leaves the record silently inert",
  "scanIgnoringComments": true,
  "extractValueSets": [
    {
      "setName": "migrationCanonPaths",
      "fromLinesMatching": "/['\"`](?<value>(?:packs|engine)\\/[A-Za-z0-9_.-]+(?:\\/[A-Za-z0-9_.-]+)+)['\"`]/",
      "inFilesMatching": "/(^|\\/)migrations\\/[^/]+\\/migration\\.mjs$/",
      "whenSetEmpty": "assertNothing"
    }
  ],
  "checkSetValues": [
    {
      "setName": "migrationCanonPaths",
      "requirePathExists": "{value}",
      "what": "the record names {value}, which is not a path in this tree",
      "fix": "repoint it at the file's current path; where the target is gone for good, delete the probe or materialization naming it rather than leave one that can never fire"
    }
  ]
}

