// Rewrite entity names inside string literals only, per a JSON map.
// usage: node rewrite.mjs <file> '{"basics":"acme-pack",...}' [onlyLines=1,2,3]
import fs from 'node:fs';
const [, , file, mapJson, onlyLines] = process.argv;
const map = JSON.parse(mapJson);
const lines = new Set(onlyLines ? onlyLines.split(',').map(Number) : null);
const src = fs.readFileSync(file, 'utf8').split('\n');
const LIT = /'([^'\\]*(?:\\.[^'\\]*)*)'|"([^"\\]*(?:\\.[^"\\]*)*)"|`([^`\\]*(?:\\.[^`\\]*)*)`/g;
let n = 0;
const out = src.map((text, i) => {
  if (onlyLines && !lines.has(i + 1)) return text;
  return text.replace(LIT, (whole) => {
    const q = whole[0];
    const body = whole.slice(1, -1);
    let next = body;
    for (const [from, to] of Object.entries(map)) {
      const esc = from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      if (next === from) { next = to; continue; }
      next = next.replace(new RegExp(`(^|/)${esc}(?=/|$)`, 'g'), `$1${to}`);
    }
    if (next !== body) n++;
    return q + next + q;
  });
});
fs.writeFileSync(file, out.join('\n'));
console.error(`${file}: ${n} literal(s) rewritten`);
EOF
