    addDeclaredCheckOwners(ctx, ctx.tracked, owners);
    const entities = [...owners.entries()].map(([key, owner]) => {
      const i = key.indexOf(':');
      return { kind: key.slice(0, i), name: key.slice(i + 1), owner };
    });

