// be the real one, and moving a module is already a change that rewrites everyone
// who imports it. Only invented values are this rule's business.
const IMPORT = /(?:^|[\s;{(])(?:import|export)\s|\bimport\s*\(|^\s*\}?\s*from\s+['"]/;
